import{c as s,$ as i,Q as e,j as r,g as a,o,n,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"Личные операции","description":"Практическое руководство по ведению журнала крупных доходов, целевых расходов, фиксации дивидендов и балансовой дельты капитала в ОмниКрафт ЕРП.","frontmatter":{"title":"Личные операции","description":"Практическое руководство по ведению журнала крупных доходов, целевых расходов, фиксации дивидендов и балансовой дельты капитала в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-26","order":18},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/operations.md","filePath":"ru/docs/spaces/moy-kapital/operations.md","lastUpdated":1795651200000}'),g={name:"ru/docs/spaces/moy-kapital/operations.md"},c={id:"личные-операции-журнал-крупных-финансовых-движении",tabindex:"-1"};function p(h,t,m,u,f,b){const l=i("DocIcon");return e(),r("div",null,[a("h1",c,[o(l,{name:"capital"}),t[0]||(t[0]=n(" Личные операции: Журнал крупных финансовых движений ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#личные-операции-журнал-крупных-финансовых-движении","aria-label":'Permalink to "Личные операции: Журнал крупных финансовых движений"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Личные операции»</strong> выступает главным регистратором ключевых денежных событий в личном финансовом пространстве создателя. В отличие от операционного учета в кассе цеха (ДДС), здесь сосредоточены исключительно фундаментальные движения средств: изъятие дивидендов из мастерской, привлечение внешних заработков, продажа личных автомобилей, покупка недвижимости, оплата дорогостоящего обучения или крупные семейные инвестиции.</p><p>Грамотное ведение журнала освобождает ремесленника от рутины домашней бухгалтерии. Система берет на себя математический расчет повседневных бытовых расходов через метод балансовой дельты капитала, требуя от мастера фиксации только тех операций, которые существенно меняют общую структуру личного благосостояния.</p><hr><h2 id="философия-учета-почему-не-нужно-записывать-чашку-кофе" tabindex="-1">Философия учета: почему не нужно записывать чашку кофе <a class="header-anchor" href="#философия-учета-почему-не-нужно-записывать-чашку-кофе" aria-label="Permalink to &quot;Философия учета: почему не нужно записывать чашку кофе&quot;">​</a></h2><p>Главный принцип ОмниКрафт ЕРП — сбережение времени и сил мастера для созидательного труда. Большинство классических программ учета личных финансов требуют от пользователя ежедневного ручного ввода каждого кассового чека, поездки на такси или покупки продуктов. На практике этот подход неизбежно приводит к выгоранию, накоплению пропущенных дней и полному отказу от финансового контроля.</p><p>В ОмниКрафт ЕРП применен альтернативный инженерный метод — <strong>учет свободных бытовых расходов по балансовой дельте</strong>:</p><ol class="craft-list-steps"><li><div><strong>Стартовый капитал на счетах:</strong><br> Сумма остатков на банковских картах, вкладах и в наличных на начало периода. </div></li><li><div><strong>+ Доходный пул:</strong><br> Чистая прибыль мастерских + сторонние личные доходы + финансовый результат инвестиций. </div></li><li><div><strong>− Крупные зафиксированные личные расходы:</strong><br> Целевые траты из журнала операций (лечение, крупные покупки, налоги, обучение). </div></li><li><div><strong>− Фактический текущий остаток капитала:</strong><br> Реальные остатки на счетах и в кошельках на текущую дату. </div></li><li><div><strong>= Автоматически рассчитанные бытовые траты:</strong><br> Незаметные расходы на повседневную жизнь без необходимости сбора мелких чеков. </div></li></ol><p>Мастеру достаточно регулярно обновлять фактические остатки на счетах во вкладке <strong>«Счета и кошельки»</strong> и заносить в журнал только крупные финансовые события. Программа автоматически сопоставляет заработанную прибыль с реальным приростом денег на картах, а всю недостающую разницу математически относит к повседневным жизненным тратам семьи.</p><hr><h2 id="математика-балансовои-дельты-и-расчет-свободных-трат" tabindex="-1">Математика балансовой дельты и расчет свободных трат <a class="header-anchor" href="#математика-балансовои-дельты-и-расчет-свободных-трат" aria-label="Permalink to &quot;Математика балансовой дельты и расчет свободных трат&quot;">​</a></h2><p>В модуле «Мой капитал» действует строгий алгоритм расчета свободных расходов мастера. Он объединяет финансовые показатели всех производственных и сервисных пространств с личными счетами и инвестициями.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Балансовая дельта</span><div class="formula-heading">Автоматический расчет свободных бытовых трат мастера</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Бытовые расходы</span><span class="math-op">=</span><span class="math-var">Накопленный доходный пул</span><span class="math-op">−</span><span class="math-group">(</span><span class="math-var">Крупные зафиксированные расходы</span><span class="math-op">+</span><span class="math-var">Дельта чистой стоимости</span><span class="math-group">)</span></div></div><div class="formula-card-bottom"><p>Накопленный доходный пул складывается из чистой прибыли рабочих пространств, зафиксированных личных доходов и финансового результата инвестиций. Если капитал вырос на меньшую величину, чем суммарно заработано за период, разница признается бытовыми расходами на жизнь без необходимости собирать чеки.</p></div></div><div class="info custom-block"><p class="custom-block-title">Физика учета: защита дельты от искажений</p><p>Если мастер продает старый автомобиль за 1 500 000 ₽ и вносит деньги на банковский счет, на счетах происходит резкий скачок ликвидности. Если не зафиксировать эту операцию в журнале как разовый личный доход, система решит, что деньги были заработаны производственным цехом, или исказит расчет семейных трат. Запись операции точно объясняет алгоритму источник средств.</p></div><hr><h2 id="архитектура-рабочего-экрана-двухпанельная-компоновка" tabindex="-1">Архитектура рабочего экрана: двухпанельная компоновка <a class="header-anchor" href="#архитектура-рабочего-экрана-двухпанельная-компоновка" aria-label="Permalink to &quot;Архитектура рабочего экрана: двухпанельная компоновка&quot;">​</a></h2><p>Экран вкладки «Личные операции» спроектирован по принципу разделения истории и ввода:</p><div class="craft-window-frame" data-title="Двухпанельная компоновка: Журнал операций и карточка записи"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:55%;">Журнал операций (История и фильтрация)</th><th style="width:45%;">Карточка записи (Форма ввода)</th></tr></thead><tbody><tr><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"></span><div><strong>Дата и время:</strong> Календарная фиксация момента проводки.</div></li><li><span class="craft-list-bullet"></span><div><strong>Категория:</strong> Статья движения личных финансов.</div></li><li><span class="craft-list-bullet"></span><div><strong>Сумма:</strong> Индикация (+ изумрудный, − кирпичный).</div></li><li><span class="craft-list-bullet"></span><div><strong>Контекст:</strong> Комментарий и источник платежа.</div></li><li><span class="craft-list-bullet"></span><div><strong>Управление:</strong> Быстрое удаление ошибочной записи.</div></li></ul></td><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"></span><div><strong>Дата операции:</strong> Выбор в интерактивном календаре.</div></li><li><span class="craft-list-bullet"></span><div><strong>Тип операции:</strong> Доход или целевой расход.</div></li><li><span class="craft-list-bullet"></span><div><strong>Категория:</strong> Рубрикатор движения средств.</div></li><li><span class="craft-list-bullet"></span><div><strong>Сумма и комментарий:</strong> Ввод размера и назначения.</div></li><li><span class="craft-list-bullet"></span><div><strong>Кнопка действия:</strong> Внесение проводки в базу данных.</div></li></ul></td></tr></tbody></table></div><h3 id="левая-панель-таблица-операции" tabindex="-1">Левая панель: Таблица операций <a class="header-anchor" href="#левая-панель-таблица-операции" aria-label="Permalink to &quot;Левая панель: Таблица операций&quot;">​</a></h3><p>Левая область экрана отведена под хронологический реестр финансовых записей:</p><ul><li><strong>Индикатор даты:</strong> фиксирует точное время и календарный день проведения операции;</li><li><strong>Категория события:</strong> понятное наименование статьи движения денег с учетом контекста типа транзакции;</li><li><strong>Суммовой столбец:</strong> отображает сумму в базовой валюте со знаком <code>+</code> изумрудного цвета для поступлений и <code>-</code> кирпично-красного цвета для списаний;</li><li><strong>Поле комментария:</strong> краткое описание цели платежа, контрагента или источника средств;</li><li><strong>Кнопка удаления:</strong> точечное удаление ошибочной транзакции с моментальным пересчетом сводных показателей;</li><li><strong>Кнопка вызова документации <code>[?]</code>:</strong> мгновенный переход к данному руководству в веб-справке.</li></ul><h3 id="правая-панель-форма-добавления-операции" tabindex="-1">Правая панель: Форма добавления операции <a class="header-anchor" href="#правая-панель-форма-добавления-операции" aria-label="Permalink to &quot;Правая панель: Форма добавления операции&quot;">​</a></h3><p>Компактная карточка ввода позволяет зарегистрировать новое движение капитала в три клика без перегрузки лишними полями.</p><hr><h2 id="справочник-полеи-карточки-записи" tabindex="-1">Справочник полей карточки записи <a class="header-anchor" href="#справочник-полеи-карточки-записи" aria-label="Permalink to &quot;Справочник полей карточки записи&quot;">​</a></h2><p>При внесении операции заполняются следующие параметры:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Поле формы</th><th style="text-align:left;">Интерфейсный элемент</th><th style="text-align:left;">Назначение и формат ввода</th><th style="text-align:left;">Пример значения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Дата операции»</strong></td><td style="text-align:left;">Адаптивный календарь</td><td style="text-align:left;">Дата фактического списания или поступления средств</td><td style="text-align:left;"><em>Выбор даты в календаре</em></td></tr><tr><td style="text-align:left;"><strong>«Тип личной операции»</strong></td><td style="text-align:left;">Выпадающий список</td><td style="text-align:left;">Вектор движения средств: доход или крупный расход</td><td style="text-align:left;"><em>Личный доход (Зарплата, фриланс)</em></td></tr><tr><td style="text-align:left;"><strong>«Категория»</strong></td><td style="text-align:left;">Динамический селектор</td><td style="text-align:left;">Целевая статья из структурированного рубрикатора</td><td style="text-align:left;"><em>Пассивный доход (вклады, аренда)</em></td></tr><tr><td style="text-align:left;"><strong>«Сумма личной операции»</strong></td><td style="text-align:left;">Числовое поле ввода</td><td style="text-align:left;">Размер платежа в базовой валюте с фильтром цифр</td><td style="text-align:left;"><em>250 000,00</em></td></tr><tr><td style="text-align:left;"><strong>«Комментарий»</strong></td><td style="text-align:left;">Многострочное поле</td><td style="text-align:left;">Детальное пояснение обстоятельств операции</td><td style="text-align:left;"><em>Дивиденды швейного цеха за 3 квартал</em></td></tr></tbody></table><hr><h2 id="классификатор-категории-личных-операции" tabindex="-1">Классификатор категорий личных операций <a class="header-anchor" href="#классификатор-категории-личных-операции" aria-label="Permalink to &quot;Классификатор категорий личных операций&quot;">​</a></h2><p>Селектор категорий автоматически адаптирует набор доступных вариантов под выбранный тип операции:</p><h3 id="_1-категории-поступлении-личныи-доход" tabindex="-1">1. Категории поступлений (Личный доход) <a class="header-anchor" href="#_1-категории-поступлении-личныи-доход" aria-label="Permalink to &quot;1. Категории поступлений (Личный доход)&quot;">​</a></h3><ul><li><strong>«Основная зарплата (наём)»:</strong> стабильные внешние оклады, если мастер совмещает собственное ремесло с контрактной работой в сторонней организации;</li><li><strong>«Разовый фриланс / подработки»:</strong> гонорары за разовые консультации, экспертные аудиты мастерских, частное репетиторство или выездные мастер-классы;</li><li><strong>«Пассивный доход (вклады, аренда)»:</strong> регулярные выплаты процентов по накопительным счетам, дивиденды публичных компаний или арендная плата от сдаваемой недвижимости;</li><li><strong>«Блогинг / донаты / реклама»:</strong> поступления от монетизации ремесленного блога, спонсорские интеграции и добровольные донаты сообщества;</li><li><strong>«Прочие личные доходы (подарки)»:</strong> целевые денежные подарки, наследство, возвраты старых личных долгов или средства от разовой продажи личных вещей.</li></ul><h3 id="_2-категории-списании-крупныи-расход" tabindex="-1">2. Категории списаний (Крупный расход) <a class="header-anchor" href="#_2-категории-списании-крупныи-расход" aria-label="Permalink to &quot;2. Категории списаний (Крупный расход)&quot;">​</a></h3><ul><li><strong>«Ипотека / Крупные кредиты»:</strong> плановые ежемесячные транши и досрочные погашения кредитов на покупку производственных площадей, мастерских или семейного жилья;</li><li><strong>«Крупные покупки (техника, мебель)»:</strong> приобретение бытовой электроники, мебели, домашнего ремонта, климатических систем или личного транспорта;</li><li><strong>«Здоровье / Обучение»:</strong> оплата медицинских услуг, стоматологии, профильных ремесленных курсов, технической литературы или университетского образования детей;</li><li><strong>«Путешествия и отдых»:</strong> затраты на семейные отпуска, загородные поездки, санатории и восстановление сил после интенсивных рабочих сезонов;</li><li><strong>«Прочие крупные расходы»:</strong> государственные пошлины, страховые премии, представительские расходы или целевая благотворительность.</li></ul><div class="tip custom-block"><p class="custom-block-title">Совет мастера: как фиксировать дивиденды собственного бизнеса</p><p>Когда мастерская генерирует чистую прибыль, вывод средств из производственной кассы на личную банковскую карту оформляется в два действия:</p><ol><li>Во вкладке <strong>«ДДС»</strong> производственного пространства регистрируется расход по статье <em>«Вывод прибыли / Дивиденды»</em>;</li><li>Во вкладке <strong>«Личные операции»</strong> вносится доход в категории <em>«Пассивный доход»</em> или <em>«Прочие личные доходы»</em> с комментарием <em>«Дивиденды мастерской»</em>. Это обеспечивает безупречную прозрачность: цех зафиксировал отток денег, а личный капитал отразил реальное увеличение благосостояния владельца.</li></ol></div><hr><h2 id="сквозные-сценарии-из-практики-ремесленника" tabindex="-1">Сквозные сценарии из практики ремесленника <a class="header-anchor" href="#сквозные-сценарии-из-практики-ремесленника" aria-label="Permalink to &quot;Сквозные сценарии из практики ремесленника&quot;">​</a></h2><h3 id="сценарии-1-продажа-старого-рабочего-фургона-и-зачисление-средств" tabindex="-1">Сценарий 1: Продажа старого рабочего фургона и зачисление средств <a class="header-anchor" href="#сценарии-1-продажа-старого-рабочего-фургона-и-зачисление-средств" aria-label="Permalink to &quot;Сценарий 1: Продажа старого рабочего фургона и зачисление средств&quot;">​</a></h3><p>Мастер обновляет автопарк: старый фургон продан за 850 000 ₽, а покупатель перевел деньги на расчетную карту.</p><ol><li>Мастер открывает форму записи операций;</li><li>Выбирает тип <strong>«Личный доход (Зарплата, фриланс)»</strong>;</li><li>Указывает категорию <strong>«Прочие личные доходы (подарки)»</strong>;</li><li>Вводит сумму <strong>850 000,00 ₽</strong>;</li><li>В поле комментария указывает: <em>«Выручка от продажи фургона ГАЗель перед закупкой нового оборудования»</em>;</li><li>Нажимает <strong>«Внести операцию»</strong>.</li></ol><p><strong>Результат:</strong> Программа учитывает 850 000 ₽ как внешний капитал. В сводке общего благосостояния этот скачок баланса на карте не будет ошибочно воспринят как сверхприбыль мастерской от продажи изделий.</p><h3 id="сценарии-2-личные-инвестиции-в-оборудование-мастерскои-заем-бизнесу" tabindex="-1">Сценарий 2: Личные инвестиции в оборудование мастерской (Заем бизнесу) <a class="header-anchor" href="#сценарии-2-личные-инвестиции-в-оборудование-мастерскои-заем-бизнесу" aria-label="Permalink to &quot;Сценарий 2: Личные инвестиции в оборудование мастерской (Заем бизнесу)&quot;">​</a></h3><p>Для покупки лазерного раскройного станка мастер решает временно перевести 400 000 ₽ из личных семейных накоплений в кассу рабочего цеха.</p><ol><li>В личном журнале фиксируется крупный расход: категория <strong>«Прочие крупные расходы»</strong>, комментарий: <em>«Вливание в оборот мастерской на покупку лазера»</em>;</li><li>Во вкладке «ДДС» рабочего пространства вносится приход по статье <em>«Личные инвестиции владельца»</em>;</li><li>В результате касса мастерской пополняется для сделки, а в сводке капитала исключается риск двойного счета одних и тех же денег.</li></ol><hr><h2 id="управление-журналом-и-пагинация" tabindex="-1">Управление журналом и пагинация <a class="header-anchor" href="#управление-журналом-и-пагинация" aria-label="Permalink to &quot;Управление журналом и пагинация&quot;">​</a></h2><p>Для поддержания максимального быстродействия даже при многолетней истории учета в реестре операций действует постраничный вывод:</p><ul><li><strong>Лимит записей:</strong> на одну страницу выводится фиксированный блок транзакций;</li><li><strong>Элементы навигации:</strong> кнопки со стрелками <strong>«Назад»</strong> и <strong>«Вперед»</strong> позволяют быстро перемещаться между страницами;</li><li><strong>Счетчик страниц:</strong> отображает текущее положение (<em>«Страница 1 из 5»</em>).</li></ul><p>Если у нескольких операций совпадают дата и время, выше будет та, которую внесли позже.</p><h3 id="пустое-состояние-и-демонстрационныи-режим" tabindex="-1">Пустое состояние и демонстрационный режим <a class="header-anchor" href="#пустое-состояние-и-демонстрационныи-режим" aria-label="Permalink to &quot;Пустое состояние и демонстрационный режим&quot;">​</a></h3><p>Если мастер только начинает настройку программы и еще не добавил ни одной записи, таблица переключается в режим приветствия:</p><ul><li>Отображается пиктограмма квитанции и поясняющий текст;</li><li>Кнопка <strong>«Режим демонстрации»</strong> открывает интерактивную подсказку, объясняющую принципы заполнения журнала на типовых примерах.</li></ul><h3 id="удаление-ошибочнои-записи" tabindex="-1">Удаление ошибочной записи <a class="header-anchor" href="#удаление-ошибочнои-записи" aria-label="Permalink to &quot;Удаление ошибочной записи&quot;">​</a></h3><p>Если при вводе суммы или категории допущена неточность:</p><ol><li>Найдите операцию в таблице журнала;</li><li>Нажмите кнопку с иконкой урны в столбце действий;</li><li>Запись исчезает из списка. Итоги и расчёт свободных расходов обновляются без её суммы.</li></ol><div class="warning custom-block"><p class="custom-block-title">Сохранение прозрачности учета</p><p>Не используйте журнал личных операций для фиксации закупки кожи, ниток, фурнитуры или клея для мастерской. Производственные затраты обязаны проходить строго через складские приходные накладные и кассу ДДС соответствующего пространства. Нарушение этого правила разрушит расчет себестоимости готовых изделий и исказит цеховую маржинальность.</p></div><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если после ввода крупной покупки сумма капитала на сводке не изменилась?</summary><div class="faq-content"><p>Журнал важных операций служит для расчета дельты бытовых расходов. Чтобы реальный остаток капитала снизился, не забудьте также актуализировать баланс списанной суммы на соответствующей банковской карте во вкладке «Счета и деньги».</p></div></details><details class="faq-item"><summary class="faq-summary">Почему операция с прошлой датой отображается выше сегодняшних проводок?</summary><div class="faq-content"><p>Таблица операций выполняет двойную сортировку: сначала по календарной дате (по убыванию), а внутри одной даты — по времени сохранения. Проверьте правильность выбранного числа в календаре формы ввода.</p></div></details><details class="faq-item"><summary class="faq-summary">Как скорректировать операцию, если при вводе была выбрана неверная статья?</summary><div class="faq-content"><p>В строке операции нажмите иконку удаления (корзину) и внесите запись заново с верной статьей и суммой. Балансовая дельта и аналитические графики пересчитаются автоматически в ту же секунду.</p></div></details></div>',58))])}const y=s(g,[["render",p]]);export{x as __pageData,y as default};
